    @SuppressLint("MissingInflatedId", "SetTextI18n")
    override fun onCreate(savedInstanceState: Bundle?) {

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
            // This code will hide the system navigation bar
            window.decorView.systemUiVisibility = (
                    View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                            or View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
                    )
        }


        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        supportActionBar?.hide()

        val arabian_shield: Button = findViewById(R.id.arabian_shield)
        val arabian_platform: Button = findViewById(R.id.arabian_platform)
        val harat: Button = findViewById(R.id.harat)
        val swahel: Button = findViewById(R.id.swahel)

        val homeBtn: FloatingActionButton = findViewById(R.id.home)
        homeBtn.setOnClickListener {
            onBackPressed()
        }

        //START: Brief button
        val brief: Button = findViewById(R.id.brief)
        brief.setOnClickListener {
            val popupView = LayoutInflater.from(this).inflate(R.layout.popup_brief, null)
            popupView.findViewById<TextView>(R.id.title).text = "جيولوجية المملكة"
            popupView.findViewById<TextView>(R.id.description).text = "تعود أقدم الصخور في المملكة إلى عصر ما قبل الكمبري، أي قبل حوالي 3 مليارات سنة. وهي تشكل أجزاء من الصفيحة العربية التي تشمل شبه الجزيرة العربية. ومع ذلك، فإن معظم مناطق المملكة العربية السعودية تقع تحت صخور حقبة الحياة الحديثة (منذ 1000 إلى 540 مليون سنة). تشمل هذه الصخور الأحدث تلك التي تعود إلى حقبة الحياة القديمة والمتوسطة، وعصور الحياة الحديثة، والتي يطلق عليها مجتمعة الغلاف الصخري لدهر الحياة الفانيروزية Phanerozoic.\n" +
                    "توجد صخور ما قبل الكمبري في الجزء الغربي من المملكة، والتي تشكل الدرع العربي. يمتد الدرع من جنوب الأردن إلى اليمن، لكن مساحته الأكبر تقع في المملكة. ويقدر طول الصفيحة العربية بحوالي 2600 كيلومتر من الشمال إلى الجنوب وحوالي 3000 كيلومتر من الشرق إلى الغرب. يحد الصفيحة العربية من الغرب صدع البحر الأحمر وصدع البحر الميت التحويلي، ومن الشرق منطقة اندساس زاغروس ومنطقة صدع أوين، ومن الشمال منطقة صدع الأناضول الشرقية، ومن الجنوب منطقة صدع عدن.\n" +
                    "ويحد صخور الدرع المكشوفة الصخور الرسوبية التي تعود إلى دهر الحياة المتوسطة في الأجزاء الوسطى والشرقية من المملكة، وفي الأجزاء الشمالية والشرقية والجنوبية الصخور الرسوبية والبركانية التي ترسبت على طول حوض البحر الأحمر. تشكل الحوض بالتزامن مع انفصال شبه الجزيرة العربية عن شمال شرق أفريقيا منذ حوالي 25 مليون سنة، مما أدى إلى تكوين الصفيحة العربية وبدء انفتاح البحر الأحمر وخليج العقبة. أدى ارتفاع حواف الصدع إلى تكوين تضاريس مائلة للصفيحة العربية، والتي كانت إلى حد كبير العامل المسؤول في تآكل صخور دهر الحياة القديمة وانكشاف الدرع العربي. الصخور النارية في الدرع العربي هي في الغالب عبارة عن تجمعات صخرية من عصر حقبة الحياة الحديثة من نظام القوس البركاني المحيطي، وإلى حد كبير، من الصخور البركانية والرسوبية التي ترسبت بشكل غير متطابق مع تسلسل القوس مع تدخلات الجرانيت واسعة النطاق. يبرز الدرع العربي المكون من الصخور النارية والمتحولة شرقًا من الحجاز إلى نجد على شكل انتفاخ يلتف حول خليج العقبة إلى نقطة تبعد أقل من 200 كيلومتر غرب الرياض ثم يتراجع باتجاه جنوب البحر الأحمر. يحتوي الدرع على العديد من البراكين الخامدة المحاطة بطبقات الحمم البركانية. تنحدر باتجاه الشرق رواسب المنصة التي توجد فيها حقول النفط. \n" +
                    "يعطي الدرع تناسقًا لجغرافية المملكة، حيث تتبع محيطه العديد من المنحدرات والصحاري الرملية. كان الدرع العربي بمثابة كتلة مستقرة Cratonic منذ أواخر عصر ما قبل الكمبري. يبرز من تحت الرمال. تشكل الرمال معظم الثلث الغربي من المملكة. تحتل رواسب المنصات البحرية جزءًا كبيرًا من الشمال، بينما تحتل التراكمات البحرية الأرضية التي يزيد ارتفاعها عن 6100 متر أحواضًا ضيقة موازية للخليج العربي والبحر الأحمر. من العصر البليستوسيني إلى التدفقات البركانية الحديثة ومخاريط الرماد تتراكب على الصخور القديمة. يميل ساحل البحر الأحمر إلى الأعلى بحيث يكون الساحل الغربي عبارة عن هضبة مرتفعة ترتفع عن البحر الأحمر 1500 متر، ويقترب ارتفاعها في بعض الأحيان من 3000 متر. تنحدر هذه الهضبة شرقًا نحو الخليج العربي، ولكن حتى هناك منحدرات أمام الخليج. \n" +
                    "يقع الغطاء الرسوبي شرق القاعدة النارية والمتحولة للدرع العربي، ويشغل نحو ثلثي مساحة أراضي المملكة العربية السعودية، أي حوالي 68%، وتقدر مساحته الإجمالية بـ 1,320,000 كم2.يعد الغطاء الرسوبي ككل جزءًا متبقيًا من طريق تيثيس البحري، والذي نتج عن التأثيرات العامة والمجمعة للعمليات الرسوبية والحركات التكتونية حول الدرع العربي. ترسبت الرواسب ذات المنشأ القاري والبحري بشكل متقطع وتجمعت في سلسلة سميكة باتجاه الشرق يصل سمكها إلى 7000 متر في حوض الخليج العربي وفي الربع الخالي. وهي تنخفض من درجة واحدة في أقدم التسلسلات الرسوبية إلى أقل من نصف درجة في التسلسلات الحديثة. تشكلت هذه التسلسلات الرسوبية على مدى فترة 541 مليون سنة تقريباً، من نهاية عصر البروتيروزويك، وتتجلى في المناطق الوسطى من المملكة على شكل حزام منحني يتجه انحناءه نحو الحافة الشرقية للجزيرة العربية. \n" +
                    "يضم الغطاء الرسوبي في المملكة أكبر الرواسب والخزانات الهيدروكربونية والمياه الجوفية والرواسب المعدنية في العالم، وتتكون من المعادن الصناعية اللافلزية، مثل البوكسيت والفوسفات والمعادن الطينية والحجر الجيري والدولوميت والجبس ورمال السيليكا والحجر الرملي، والرمال السوداء، بالإضافة إلى المعادن الأساسية وغيرها. وقد تحتوي هذه الصخور الرسوبية أيضًا على عناصر مشعة، مثل اليورانيوم، والعناصر الأرضية النادرة التي ترتبط برواسب الفوسفات.\n" +
                    "تتميز المملكة بوجود القمم الصخرية المرتفعة والحادة، ويوجد في المملكة ثلاثة أقسام للجبال وهي:\n" +
                    "•\tجبال السروات: تقع جبال السروات في جنوب المملكة، وهي عالية الارتفاع. يبلغ ارتفاعها حوالي 9000 قدم. وتنحدر منها مجموعة من الأودية شرقا وغربا. مثل وادي جازان ووادي الرمة ووادي بيشه ووادي الحمض ووادي نجران ووادي ينبع ووادي فاطمة ووادي تثليث.\n" +
                    "•\tجبال الحجاز: تقع في منتصف السلاسل الجبلية. وتمتد من شمال مدينة مكة حتى دائرة عرض 28 شمالا.\n" +
                    "•\tجبال مدين: تقع جبال مدين شمال المرتفعات الجبلية السعودية، يبلغ ارتفاعها حوالي 2500م فوق مستوى سطح البحر.\n" +
                    "          وهناك أيضا العديد من الهضاب ومن أهمها ما يلي:\n" +
                    "•\tهضبة نجد: تقع هضبة نجد بين رمال الدهناء في الشرق وجبال الحجاز في الغرب، بالقرب من صحراء الدهناء، يوجد من ضمنها جبال طويق. من أشهر الأودية التي تشق هضبة نجد: وادي حنيفة ووادي الباطن ووادي السرحان.\n" +
                    "•\tهضاب شرق المملكة: هي الهضاب التي تمتد على طول ساحل الخليج العربي ما بين السهل الساحلي شرقا وصحراء الدهناء غربا، وصحراء الربع الخالي جنوبا، حتى وادي الباطن الواقع شمالا. من أشهر هذه الهضاب: هضبة الدبة والصمان والجافورة.\n" +
                    "•\tهضاب شمال المملكة: هي الهضاب الممتدة من صحراء النفوذ حتى حدود الكويت في الشمال الشرقي، وبعضها يمتد إلى الحدود الأردنية الكويتية. ومن أشهر هذه الهضاب: حوض الحماد، وهضبة الحرة، وهضبة الحجرة، وهضبة وادي السرحان.\n" +
                    "•\tهضاب غرب المملكة: هي الهضاب التي تمتد من شمال إلى جنوب المملكة على طولها، ومن أهم الهضاب في غرب المملكة: هضبة الحسمى والحرات، ونجران، وعسير، والحجاز.\n" +
                    "أما الصحاري في المملكة فإنها تنقسم إلىى ثلاثة أجزاء وهي:\n" +
                    "•\tصحراء النفوذ الكبرى: تقع صحراء النفوذ الكبير في شمال المملكة، تمتد على مسافة 90 كيلومتراً من قرية جُبّة وحتى مدينة سكاكا، وتمتد من الزلفي مسافة 300 كيلومتراً حتى تصل إلى حدود حائل. وتمتد على مساحة 103,600 كيلومتر مربع في محافظات الجوف وتبوك وحائل، وهي تعتبر صحراء جرداء، تندر فيها الامطار.\n" +
                    "•\tصحراء الربع الخالي: تقع صحراء الربع الخالي في جنوب المملكة، تبلغ مساحتها 650 ألف كيلو متر مربع، وهي جزء من المنطقة الشرقية ومحافظتي نجران والرياض. توجد فيها كل أشكال الرمال المعروفة مثل: العروق، والهلالية، و الكثبان النجمية.\n" +
                    "•\tصحراء الدهناء: تقع صحراء الدهناء على طول طريق الدمام السريع، تمتد من محافظة الزلفى في وسط المملكة وتمر بالقصيم ومنطقة حائل شمالا. وتعتبر جسرا رمليا بين صحراء الربع الخالي وصحراء النفوذ الكبرى.\n" +
                    "          تعد السهول من تضاريس المملكة العربية السعودية البارزة، بالأخص أنها تمتد   \n" +
                    "          على طول سواحل المملكة، ومنها ما يلي:\n" +
                    "•\tسهول شرقية: هي السهول الممتدة من ساحل الخليج العربي حتى هضبة الصمان. والمطلة على الخليج الغربي. وهي سهول منبسطة تغطي الرمال أجزاء كبيرة منها وبعض أجزائها تحول إلى مسطحات ملحية.\n" +
                    "•\tالسهول الغربية: هي السهول التي تمتد على طول ساحل البحر الأحمر حتى جبال السروات والتي تعرف بسهول تهامة. وهي تتسع في الجنوب وتضيق في الشمال.\n" +
