    private fun setupClickListener() {
        val layerIds = polygonInfo.keys.toList() // Ensure these are correct
        val queryOptions = RenderedQueryOptions(layerIds, null)

        mapboxMap.addOnMapClickListener { point ->
            val screenPoint = mapboxMap.pixelForCoordinate(point)
            mapboxMap.queryRenderedFeatures(screenPoint, queryOptions) { expected ->
                expected.value?.let { features ->
                    if (features.isNotEmpty()) {
                        val feature = features.first()
                        val sourceLayer = feature.sourceLayer

                        Log.d("MapClick", "Feature: $feature")
                        Log.d("MapClick", "Source Layer: $sourceLayer")

                        polygonInfo[sourceLayer]?.let { (title, description) ->
                            handlePolygonClick(title, description)
                        } ?: Log.d("MapClick", "No matching polygon info found for source layer: $sourceLayer")
                    } else {
                        Log.d("MapClick", "No features found")
                    }
                }
            }
            true
        }
    }


    @SuppressLint("InflateParams")
    private fun handlePolygonClick(title: String, description: String) {
        val popupView = LayoutInflater.from(this).inflate(R.layout.polygon_popup_layout, null)
        val tvTitle = popupView.findViewById<TextView>(R.id.tvTitle)
        val tvDescription = popupView.findViewById<TextView>(R.id.tvDescription)
        val btnClose = popupView.findViewById<Button>(R.id.btnClose)

        tvTitle.text = title
        tvDescription.text = description

        val popupWindow = PopupWindow(popupView,
            LinearLayout.LayoutParams.WRAP_CONTENT,
            LinearLayout.LayoutParams.WRAP_CONTENT,
            true)

        btnClose.setOnClickListener { popupWindow.dismiss() }

        // For example, show it at the center of the screen, adjust as needed
        popupWindow.showAtLocation(popupView, Gravity.CENTER, 0, 0)
    }





    @SuppressLint("InflateParams")
    private fun showPopup(title: String, description: String, imageResId: Int) {
        val popupView = LayoutInflater.from(this).inflate(R.layout.popup_layout, null)
        popupView.findViewById<TextView>(R.id.title).text = title
        popupView.findViewById<TextView>(R.id.description).text = description
        popupView.findViewById<ImageView>(R.id.image).setImageResource(imageResId)

        val dialog = Dialog(this)
        dialog.setContentView(popupView)

        val displayMetrics = resources.displayMetrics
        val screenWidth = displayMetrics.widthPixels

        dialog.window?.setLayout((screenWidth * 0.9).toInt(), LinearLayout.LayoutParams.WRAP_CONTENT)

        dialog.show()

        val closeButton = popupView.findViewById<Button>(R.id.closeButton)
        closeButton.setOnClickListener {
            dialog.dismiss()
        }
    }

    private fun setMapStyle(assetPath: String) {
        val styleJson = loadJsonFromAsset(assetPath)
        mapboxMap.loadStyleJson(styleJson)
    }

    private fun loadJsonFromAsset(filename: String): String {
        return assets.open(filename).bufferedReader().use { it.readText() }
    }

